using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    //  CalculateTotal – DataRow (compile-time constants)
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(10.00, 1, 0.0,  10.00,  DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0,  50.00,  DisplayName = "Multiple items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00,  DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62,  DisplayName = "Fractional price, 8% tax")]
    [DataRow(0.00,  5, 0.10, 0.00,   DisplayName = "Zero unit price")]
    [DataRow(10.00, 0, 0.10, 0.00,   DisplayName = "Zero quantity")]
    [DataRow(99.99, 1, 1.0,  199.98, DisplayName = "100% tax rate")]
    public void CalculateTotal_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal(
            (decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    //  CalculateTotal – invalid inputs
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.00, 1,  0.10, DisplayName = "Negative unit price")]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity")]
    [DataRow(10.00, 1,  -0.1, DisplayName = "Negative tax rate")]
    [DataRow(10.00, 1,  1.01, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidInputs_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(
                (decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – DynamicData (allows decimal precision)
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> DiscountTestCases =>
    [
        [100.00m,  0m,    100.00m],   // No discount
        [100.00m,  10m,   90.00m],    // 10% off
        [100.00m,  50m,   50.00m],    // 50% off
        [100.00m,  100m,  0.00m],     // 100% off
        [59.99m,   25m,   44.9925m],  // Fractional result
        [0.00m,    50m,   0.00m],     // Zero price
        [200.00m,  33.33m, 133.34m],  // Repeating-decimal percent
    ];

    [TestMethod]
    [DynamicData(nameof(DiscountTestCases))]
    public void ApplyDiscount_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – invalid discount percentages
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1.0,  DisplayName = "Negative discount")]
    [DataRow(100.1, DisplayName = "Discount above 100")]
    public void ApplyDiscount_InvalidPercent_Throws(double discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));
    }

    // ───────────────────────────────────────────────
    //  DynamicData from method (alternative pattern)
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> BulkOrderScenarios()
    {
        // Large quantity
        yield return [1.00m, 1000, 0.05m, 1050.00m];
        // High-value item
        yield return [999.99m, 2, 0.0725m, 2144.9786m];
        // Minimal purchase
        yield return [0.01m, 1, 0.0m, 0.01m];
    }

    [TestMethod]
    [DynamicData(nameof(BulkOrderScenarios), DynamicDataSourceType.Method)]
    public void CalculateTotal_BulkScenarios_ReturnsExpected(
        decimal unitPrice, int quantity, decimal taxRate, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result);
    }
}

